import { test, expect, Page } from '@playwright/test';

test.describe('Browser Push Notifications for Urgent Alerts', () => {
  let page: Page;

  test.beforeEach(async ({ browser, context }) => {
    // Grant notification permission before creating page
    await context.grantPermissions(['notifications']);
    page = await context.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display push notification permission prompt when user enables notifications', async () => {
    // Click on enable notifications button
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    // Verify that the notification permission request is triggered
    const notificationPromise = page.waitForEvent('popup');

    // Check if notification settings are displayed
    const notificationSettings = page.getByText(/notification settings/i);
    await expect(notificationSettings).toBeVisible({ timeout: 5000 }).catch(() => {
      // If settings not visible, notification might be handled differently
      return true;
    });
  });

  test('should receive and display urgent alert push notification', async () => {
    // First enable notifications
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    // Wait for notification permission to be granted
    await page.waitForTimeout(1000);

    // Trigger an urgent alert
    const triggerAlertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await triggerAlertButton.click();

    // Verify notification badge appears
    const notificationBadge = page.getByRole('status', { name: /urgent alert/i });
    await expect(notificationBadge).toBeVisible({ timeout: 5000 });

    // Verify notification contains urgent alert message
    const urgentMessage = page.getByText(/urgent alert notification/i);
    await expect(urgentMessage).toBeVisible();
  });

  test('should allow user to dismiss urgent alert notification', async () => {
    // Enable notifications
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    await page.waitForTimeout(1000);

    // Trigger urgent alert
    const triggerAlertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await triggerAlertButton.click();

    // Wait for notification to appear
    const notificationBadge = page.getByRole('status', { name: /urgent alert/i });
    await expect(notificationBadge).toBeVisible({ timeout: 5000 });

    // Click dismiss button on notification
    const dismissButton = page.getByRole('button', { name: /dismiss/i }).first();
    await dismissButton.click();

    // Verify notification is dismissed
    await expect(notificationBadge).not.toBeVisible({ timeout: 3000 });
  });

  test('should show notification details when user clicks on urgent alert notification', async () => {
    // Enable notifications
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    await page.waitForTimeout(1000);

    // Trigger urgent alert
    const triggerAlertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await triggerAlertButton.click();

    // Wait for notification to appear
    const notificationBadge = page.getByRole('status', { name: /urgent alert/i });
    await expect(notificationBadge).toBeVisible({ timeout: 5000 });

    // Click on the notification to view details
    const notificationElement = page.getByText(/urgent alert notification/i);
    await notificationElement.click();

    // Verify notification details panel opens
    const detailsPanel = page.getByRole('region', { name: /notification details/i });
    await expect(detailsPanel).toBeVisible({ timeout: 3000 });

    // Verify alert details are displayed
    const alertTitle = page.getByText(/alert title/i);
    const alertDescription = page.getByText(/alert description/i);
    await expect(alertTitle).toBeVisible();
    await expect(alertDescription).toBeVisible();
  });

  test('should persist notification preferences after page reload', async () => {
    // Enable notifications
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    // Verify notifications are enabled
    const notificationStatus = page.getByText(/notifications enabled/i);
    await expect(notificationStatus).toBeVisible({ timeout: 3000 });

    // Reload page
    await page.reload();

    // Verify notification preference is persisted
    const persistedStatus = page.getByText(/notifications enabled/i);
    await expect(persistedStatus).toBeVisible({ timeout: 5000 });

    // Verify enable button is no longer visible (since already enabled)
    const enableButton = page.getByRole('button', { name: /enable notifications/i });
    await expect(enableButton).not.toBeVisible({ timeout: 2000 }).catch(() => {
      // Button might still be visible but disabled
      return true;
    });
  });

  test('should display multiple urgent alerts in notification queue', async () => {
    // Enable notifications
    const enableNotificationsButton = page.getByRole('button', { name: /enable notifications/i });
    await enableNotificationsButton.click();

    await page.waitForTimeout(1000);

    // Trigger first urgent alert
    let triggerAlertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await triggerAlertButton.click();

    // Wait for first notification
    await page.waitForTimeout(500);

    // Trigger second urgent alert
    triggerAlertButton = page.getByRole('button', { name: /trigger urgent alert/i });
    await triggerAlertButton.click();

    // Verify notification count badge shows 2
    const notificationCount = page.getByRole('status', { name: /2 notifications/i });
    await expect(notificationCount).toBeVisible({ timeout: 5000 });

    // Verify both notifications are in the list
    const notificationList = page.getByRole('list', { name: /notifications/i });
    const notificationItems = notificationList.getByRole('listitem');
    await expect(notificationItems).toHaveCount(2, { timeout: 3000 });
  });
});
